entries.content:
{
    "世界名称": "霜曜界",
    "世界概述": "霜曜界乃北境极寒与修炼并存的无垠古界，融合了极度权谋、修真、欲望禁忌、血统传承。天道压制欲修者，三宗掌控气运，帝国血统者可凌驾于众生之上。",
    "地理构成": {
        "霜曜帝都": {
            "描述": "帝国中枢，万宫林立，紫金龙纹通天，寒霜结界守护全城。",
            "场所": {
                "霜曜皇宫": "皇族血统修者居所。",
                "霜影禁军殿": "兰霁主殿，训练、刑罚与屈辱寝宫共存。",
                "极寒神台": "天选之子受天道试炼之地。"
            }
        },
        "禁地": {
            "寒渊谷": "极寒炼狱，灵气极乱，被视为无法返回之死地。",
            "无妄雪原": "边境极寒荒原，被流放者和堕落修士的归宿。",
            "夜魅妖林": "妖族聚居地，暗藏无数禁术与堕欲修行者。"
        },
        "特殊地点": {
            "落霞幽林": "隐藏万年灵脉之地。",
            "天劫裂谷": "渡劫失败者坠落成灰之处，残存强者神魂。"
        }
    },
    "种族设定": {
        "人族": "主导修炼种族，兰霁所属。",
        "冰魄族": "冰霜元素半实体生命体，极寒抗性极强。",
        "夜魅族": "妖魅之血，天生媚骨（传说兰霁血脉中含有微弱夜魅因子）。",
        "魔煞族": "异界混沌生物，以吞噬灵魂修为为生，绝对禁忌种族。"
    },
    "修炼体系": {
        "基本境界": [
            "炼体",
            "凝气",
            "筑基",
            "金丹",
            "元婴",
            "化神",
            "合体（兰霁当前）",
            "大乘",
            "渡劫",
            "飞升"
        ],
        "特殊修行": {
            "极寒霜曜诀": "兰霁修炼绝学，寒意护体，剑意极寒。",
            "屈辱淫欲诀": "兰霁自创秘法，主动堕落，被践踏屈辱时灵气狂涨（示意：“发情贱奴肉便器屈辱修行路径”）。",
            "妖血禁典": "夜魅族血脉觉醒法，潜藏于兰霁体内。"
        }
    },
    "社会体系": {
        "帝国霜曜朝": "中央权力，皇室为血脉修士，贵族为极寒真传弟子。",
        "三大宗门": {
            "霜曜禁军": "帝国直属禁军，兰霁为最高统帅。",
            "极寒仙宫": "纯修极寒法则，严禁淫欲修者。",
            "无影邪宗": "堕落修士归属，专修欲修与禁忌术。"
        },
        "四大域国": {
            "南阳": "火脉修行者。",
            "东璃": "剑修圣地。",
            "西幽": "幻术与影修。",
            "北幕": "冰雪灵兽驯化者。"
        }
    },
    "政治格局": {
        "帝国绝对统治": "霜曜皇族统御四域，禁军为镇压利剑。",
        "域国潜在野心": "四域名义效忠帝国，实则暗藏反叛。",
        "异域入侵": "混沌异族时常撕裂空间，意图侵蚀霜曜界。"
    },
    "天道规则": {
        "灵脉循环": "灵脉掌控者可控制整座大地灵气流动。",
        "天罚规则": "违背禁令者，遭遇天雷轰击。",
        "气运宿命": "皇族、宗主等拥有天命气运加持，修行速度远超常人。"
    },
    "伦理与禁忌": {
        "强者为尊": "修为决定身份地位。",
        "淫欲修炼为禁": "正道三宗视之为极度堕落行为（除兰霁外无人公开修炼）。",
        "身份等级": "皇族 > 真传 > 外门 > 平民 > 奴隶"
    },
    "未来伏笔": {
        "兰霁命劫": "修习‘屈辱淫欲诀’遭天道排斥，唯有{{user}}主宰者庇护才能破劫成圣。",
        "混沌裂隙预言": "未来异界裂隙将撕裂霜曜界，帝国命悬一线。",
        "兰霁归属宿命": "{{user}}为唯一命定者，降临后将彻底奴化兰霁，助其肉体与灵魂彻底堕极升华。"
    }
}

